import { readdirSync, readFileSync, statSync, writeFileSync, existsSync } from 'node:fs';
import path from 'node:path';
import { reportsDirectory, projectRoot } from '../src/paths.js';

/**
 * Publish the latest agent reports to the deployed front: reads every
 * `<slug>-report.md` under src/reporting/reports/ and rewrites
 * apps/defi-web/src/data/agent-reports.ts (a generated file - the front is
 * static on Vercel and cannot reach this local backend, so reports ship as
 * a build-time snapshot). Run it after the reports change, then redeploy the
 * front. Part of no pipeline on purpose: the reports change when an operator
 * runs an agent, not on a schedule.
 */
const targetPath = path.resolve(projectRoot, '..', 'defi-web', 'src', 'data', 'agent-reports.ts');

if (!existsSync(reportsDirectory)) {
  console.error(`export-agent-reports: no reports directory at ${reportsDirectory}`);
  process.exit(1);
}

const reports: Record<string, { generatedAt: string; markdown: string }> = {};
for (const file of readdirSync(reportsDirectory).sort()) {
  if (!file.endsWith('-report.md')) continue;
  const slug = file.replace(/-report\.md$/, '');
  const filePath = path.join(reportsDirectory, file);
  reports[slug] = {
    generatedAt: statSync(filePath).mtime.toISOString(),
    markdown: readFileSync(filePath, 'utf8').trim(),
  };
}

const banner = `// GENERATED by apps/spv-backend/scripts/export-agent-reports.ts - do not edit.
// Snapshot of the local agent runs (src/reporting/reports/); regenerate with
// \`pnpm --filter spv-backend export-reports\` then redeploy the front.

export interface AgentReport {
  generatedAt: string;
  markdown: string;
}

export const agentReports: Record<string, AgentReport> = `;

writeFileSync(targetPath, banner + JSON.stringify(reports, null, 2) + ';\n');
console.log(
  `export-agent-reports: ${Object.keys(reports).length} report(s) -> ${path.relative(process.cwd(), targetPath)}`
);
for (const [slug, report] of Object.entries(reports)) {
  console.log(`  ${slug}: ${report.generatedAt} (${report.markdown.length} chars)`);
}
